const raw = $input.all()[0]?.json || {};
const niche = raw.niche || '';

// design could be:
// - a JSON string containing the concept object
// - an object directly
// - raw itself (flat record from image generator)
let design = {};
const rawDesign = raw.designs || raw.concept || null;

if (rawDesign === null) {
  // raw IS the design record
  design = raw;
} else if (typeof rawDesign === 'string') {
  try {
    const parsed = JSON.parse(rawDesign);
    design = Array.isArray(parsed) ? (parsed[0] || {}) : parsed;
  } catch(_) {
    // It's a plain string keyword — use raw as the design
    design = raw;
  }
} else if (Array.isArray(rawDesign)) {
  design = rawDesign[0] || {};
} else {
  design = rawDesign;
}

// Ensure design is a plain object not a string
if (typeof design !== 'object' || design === null) design = raw;

return [{ json: { niche: niche || design.niche || '', ...design } }];

const ctx = $('Unpack Design').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\{[\s\S]*\}/);
let seo = {};
try { seo = JSON.parse(match?.[0] || '{}'); } catch (_) {}

return [{
  json: {
    ...ctx,
    etsyTitle:          seo.etsyTitle          || '',
    etsyDescription:    seo.etsyDescription    || '',
    etsyTags:           seo.etsyTags           || [],
    amazonTitle:        seo.amazonTitle        || '',
    amazonBulletPoints: seo.amazonBulletPoints || [],
    amazonKeywords:     seo.amazonKeywords     || '',
    seoFileName:        seo.fileName           || '',
    altText:            seo.altText            || '',
    searchTerms:        seo.searchTerms        || []
  }
}];

const item = $input.first().json;
const niche = item.niche || $('Unpack Design').first()?.json?.niche || '';
return [{ json: { ...item, niche } }];
